import json
import os
import subprocess
import sys
import shutil

# --- Configuration Paths ---
GLOBAL_JSON_FILE = "./config/config.json"

def generate_cmake_options(config_data, output_file):
    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    lines = [
        "# ==================================================================",
        "# AUTOGENERATED FILE - DO NOT EDIT",
        "# Generated by build_engine.py from config.json",
        "# =================================================================="
    ]
    
    # Matches the root-level CMAKE_OPTIONS block in your config_2.json
    cmake_options = config_data.get("CMAKE_OPTIONS", {})
    for key, node in cmake_options.items():
        if isinstance(node, dict) and "value" in node:
            val = node["value"]
            # FORCE ensures this overrides CMake's cached defaults
            lines.append(f'set({key} "{val}" CACHE STRING "Auto-generated from JSON" FORCE)')
            
    with open(output_file, 'w') as f:
        f.write("\n".join(lines) + "\n")
    print(f"[Python] Generated CMake options: {output_file}")

def generate_compile_macros(compile_data, output_file):
    os.makedirs(os.path.dirname(output_file), exist_ok=True)
    lines = [
        "// ==================================================================",
        "// AUTOGENERATED FILE - DO NOT EDIT",
        "// Generated by build_engine.py from config.json",
        "// ==================================================================",
        "#pragma once",
        ""
    ]
    
    def extract_macros(d, category=""):
        for key, node in d.items():
            if isinstance(node, dict):
                if "value" in node:
                    val = node["value"]
                    lines.append(f"#define {key} {val}")
                else:
                    extract_macros(node, key)

    extract_macros(compile_data)
    
    with open(output_file, 'w') as f:
        f.write("\n".join(lines) + "\n")
    print(f"[Python] Generated compile-time macros: {output_file}")


def generate_runtime_config(json_data, output_file):
    lines = [
        "# ==================================================================",
        "# RUNTIME SETTINGS",
        "# Only parameters required by your active compile-time choices are listed.",
        "# =================================================================="
    ]
    
    compile_time = json_data.get("COMPILE_TIME", {})
    runtime = json_data.get("RUNTIME", {})
    
    def write_block(block_dict, prefix=""):
        for k, v in block_dict.items():
            if isinstance(v, dict):
                # If it has a type or description, it's a parameter (leaf)
                if "type" in v or "description" in v:
                    v_type = v.get("type", "unknown")
                    default = '""' if v_type == "string" else "false" if v_type == "bool" else "0"
                    lines.append(f"{v_type} {prefix}{k}={default} # {v.get('description', '')}")
                else:
                    # Otherwise, it's a sub-dictionary. Recurse and append prefix.
                    write_block(v, prefix=f"{prefix}{k}.")

    # 1. Universal Blocks
    for block in ["CORE", "INTEGRATOR", "IO", "INITIAL_CONDITIONS"]:
        lines.append(f"\n# --- {block.replace('_', ' ')} ---")
        write_block(runtime.get(block, {}))

    # 2. Physics Modules (Dynamic routing for Gravity & Hydro)
    for module in ["GRAVITY", "HYDRO"]:
        mod_compile = compile_time.get(module, {})
        if mod_compile.get(f"{module}_ENABLED", {}).get("value") == 1:
            lines.append(f"\n# --- {module} ---")
            
            mod_runtime = runtime.get(module, {})
            framework = mod_compile.get(f"{module}_FRAMEWORK", {}).get("value")
            
            # Keep only base parameters (leaves) OR the selected framework (branch)
            active_params = {k: v for k, v in mod_runtime.items() if k == framework or "type" in v or "description" in v}
            write_block(active_params)

    # 3. Domains
    domain_compile = compile_time.get("DOMAIN", {})
    domain_runtime = runtime.get("DOMAIN", {})
    
    for slot in ["MESH_SLOT_1", "MESH_SLOT_2"]:
        slot_type = domain_compile.get(slot, {}).get("value", "NO_DOMAIN")
        if slot_type != "NO_DOMAIN":
            lines.append(f"\n# --- DOMAIN: {slot} ({slot_type}) ---")
            slot_key = slot_type.replace(" ", "_")
            if slot_key in domain_runtime:
                write_block(domain_runtime[slot_key], prefix=f"{slot}.")

    with open(output_file, 'w') as f:
        f.write("\n".join(lines) + "\n")
    print(f"[Python] Generated runtime config map: {output_file}")


def generate_execution_txt(json_data, output_file):
    lines = [
        "# ==================================================================",
        "# ENGINE ACTION",
        "# Define action that should be taken by a compiled engine.",
        "# =================================================================="
    ]
    
    engine_action_config = json_data.get("ENGINE_ACTION", {})

    for key, subdic in engine_action_config.items():
        type = subdic["type"]
        default = '""' if type == "string" else "0"
        lines.append(f"{type} {key}={default}")

    with open(output_file, 'w') as f:
        f.write("\n".join(lines) + "\n")
    print(f"[Python] Generated execution file: {output_file}")


def compile_engine(build_dir, run_configure):
    """
    Invokes CMake to configure and build the NBody_Engine project.
    """
    print(f"\n[Python] Targeting build directory: {build_dir}")
    try:
        # Only run the configuration step if explicitly requested
        if run_configure:
            print("[Python] Configuring CMake...")
            subprocess.run(["cmake", "-S", ".", "-B", build_dir], check=True)
        else:
            print("[Python] Skipping CMake configuration (using existing cache)...")
        
        print("\n[Python] Compiling with CMake...")
        #cores = str(os.cpu_count() or 4)
        #subprocess.run(["cmake", "--build", build_dir, "--config", "Release", "-j", cores], check=True)
        subprocess.run(["cmake", "--build", build_dir, "--config", "Release"], check=True)
        
        print("\n[Python] Compilation Successful!")
        print(f"[Python] Run your simulation with: ./{build_dir}/NBody_Engine")
        
    except subprocess.CalledProcessError:
        print("\n[Error] CMake build pipeline failed.")
        sys.exit(1)


def main():
    # 1. Ask for a valid project name
    while True:
        project_name = input("Enter a project/build name: ").strip()
        if project_name:
            break
        print("[Error] Project name cannot be empty or contain only spaces.")

    # Setup isolated directories
    build_dir = os.path.join("build", project_name)
    generated_dir = os.path.join(build_dir, "generated")
    receipt_file = os.path.join(build_dir, "build_config.json")
    
    run_configure = True
    json_to_load = GLOBAL_JSON_FILE

    # 3 & 4. Handle existing builds smartly
    if os.path.isdir(build_dir):
        ans = input(f"[Python] Build '{project_name}' exists. Reconfigure CMake (e.g., added new source files)? (y/N): ").strip().lower()
        if ans == 'y':
            run_configure = True
            if os.path.exists(receipt_file):
                json_to_load = receipt_file
                print(f"[Python] Reconfiguring using receipt: {receipt_file}")
            else:
                print(f"[Warning] Receipt not found. Falling back to global config: {GLOBAL_JSON_FILE}")
        else:
            run_configure = False
            # Still load the receipt to ensure runtime configs match the current build
            if os.path.exists(receipt_file):
                json_to_load = receipt_file
            print("[Python] Proceeding with compilation only.")

    if not os.path.exists(json_to_load):
        print(f"[Error] Could not find configuration file: {json_to_load}")
        sys.exit(1)

    with open(json_to_load, 'r') as f:
        config_data = json.load(f)

    # Ensure isolated generated directory exists
    os.makedirs(generated_dir, exist_ok=True)

    # 2. Produce the configuration receipt inside the build folder
    if run_configure or json_to_load == GLOBAL_JSON_FILE:
        with open(receipt_file, 'w') as f:
            json.dump(config_data, f, indent=4)
        print(f"[Python] Saved configuration receipt to: {receipt_file}")

    # Define dynamic output paths inside the isolated build folder
    CMAKE_OPTIONS_FILE = os.path.join(generated_dir, "cmake_options.cmake")
    MACRO_HEADER_FILE = os.path.join(generated_dir, "compile_macros.hpp")
    RUNTIME_CFG_FILE = os.path.join(build_dir, "runtime_settings.txt")
    EXEC_TXT_FILE = os.path.join(build_dir, "execution.txt")

    # Generate all necessary files
    generate_cmake_options(config_data, CMAKE_OPTIONS_FILE)
    generate_compile_macros(config_data.get("COMPILE_TIME", {}), MACRO_HEADER_FILE)
    generate_runtime_config(config_data, RUNTIME_CFG_FILE)
    generate_execution_txt(config_data, EXEC_TXT_FILE)
    
    # Trigger the CMake build pipeline
    compile_engine(build_dir, run_configure)

if __name__ == "__main__":
    main()